186: pub fn classify_version(version: u8) -> Result<VersionCapabilities, FlightReaderError> {
187:     match version {
188:         1..=6 => Ok(VersionCapabilities {
189:             version,
190:             record_len_width: 1,
191:             scramble_type: ScrambleType::None,
192:             details_location: DetailsLocation::EndOfFile,
